$ErrorActionPreference = "Stop"

if (-not (Test-Path "manage.py")) {
    Write-Error "ERROR: manage.py not found. Please cd to your dashboard folder first."
    exit 1
}

$dashboardDir = Get-Location
$posPath = Join-Path $dashboardDir "templates\sales\pos.html"

if (Test-Path $posPath) {
    $backupPath = $posPath + ".backup." + (Get-Date -Format "yyyyMMddHHmmss")
    Copy-Item -Path $posPath -Destination $backupPath -Force
    Write-Host "Backup created: $backupPath" -ForegroundColor Cyan
}

$dir = Split-Path -Parent $posPath
if (-not (Test-Path $dir)) {
    New-Item -ItemType Directory -Path $dir -Force | Out-Null
}

$base64 = ""
$bytes = [System.Convert]::FromBase64String($base64)
[System.IO.File]::WriteAllBytes($posPath, $bytes)

Write-Host ""
Write-Host "========================================" -ForegroundColor Green
Write-Host "  pos.html UPDATED SUCCESSFULLY!" -ForegroundColor Green
Write-Host "========================================" -ForegroundColor Green
Write-Host ""
Write-Host "VS Code fix: Django template loop moved to" -ForegroundColor Yellow
Write-Host "  <script type='application/json'> block" -ForegroundColor White
Write-Host "  (VS Code ignores it, no red squiggles)" -ForegroundColor White
Write-Host ""
Write-Host "Features:" -ForegroundColor Yellow
Write-Host "  - Type-to-search customer autocomplete" -ForegroundColor White
Write-Host "  - Click to select, X to clear" -ForegroundColor White
Write-Host "  - + button / Add New in dropdown" -ForegroundColor White
Write-Host "  - Auto-capture camera (silent every 2s)" -ForegroundColor White
Write-Host "  - Phone required, name auto-generates" -ForegroundColor White
Write-Host "  - Auto-modal if total >= 1000" -ForegroundColor White
Write-Host ""
Write-Host "Next: python manage.py runserver" -ForegroundColor Cyan
